mapper.select:
select W.Id,job_id as jobId ,job_name as jobName,comp_id as compId,comp_name as compName,dep_id as depId,dep_name as depName, create_time as createTime, park_name as parkName from SMT_WHITE_JOB W inner join SMT_PARK P on W.PARK_ID = P.ID
AND job_name LIKE CONCAT(CONCAT('%',#{query.jobName}),'%')
AND PARK_ID =#{query.parkId}
and W.PARK_ID in
#{item}
order by CREATE_TIME desc
